import flask
from flask import request, jsonify
import psycopg2
import os
import hashlib
import hmac

app = flask.Flask(__name__)

# Database connection pool
def get_db_connection():
    return psycopg2.connect(
        host=os.environ.get('DB_HOST', 'localhost'),
        port=os.environ.get('DB_PORT', '5432'),
        dbname=os.environ.get('DB_NAME', 'appdb'),
        user=os.environ.get('DB_USER', 'appuser'),
        password=os.environ.get('DB_PASSWORD', '')
    )

# Middleware: verify request signature (optional, based on config)
@app.before_request
def verify_signature():
    if os.environ.get('REQUIRE_HMAC') == '1':
        sig = request.headers.get('X-Signature')
        if not sig:
            return jsonify({'error': 'missing signature'}), 401
        secret = os.environ.get('HMAC_SECRET', '').encode()
        body = request.get_data()
        expected = hmac.new(secret, body, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected):
            return jsonify({'error': 'invalid signature'}), 403

@app.route('/api/v1/users/search', methods=['GET'])
def search_users():
    """Search users by various criteria. Supports flexible filtering."""
    username = request.args.get('username', '')
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    sort_by = request.args.get('sort', 'created_at')
    order = request.args.get('order', 'DESC')
    limit = request.args.get('limit', '50')

    # Build query with filters
    conditions = []
    if username:
        conditions.append(f"username LIKE '%{username}%'")
    if department:
        conditions.append(f"department = '{department}'")
    if role:
        conditions.append(f"role = '{role}'")

    where_clause = ' AND '.join(conditions) if conditions else '1=1'

    # Note: sort_by is validated against allowed columns
    allowed_sorts = ['created_at', 'username', 'department', 'last_login']
    if sort_by not in allowed_sorts:
        sort_by = 'created_at'
    if order.upper() not in ('ASC', 'DESC'):
        order = 'DESC'

    query = f"SELECT id, username, department, role, created_at FROM users WHERE {where_clause} ORDER BY {sort_by} {order} LIMIT {limit}"

    try:
        conn = get_db_connection()
        cur = conn.cursor()
        cur.execute(query)
        rows = cur.fetchall()
        results = []
        for row in rows:
            results.append({
                'id': row[0],
                'username': row[1],
                'department': row[2],
                'role': row[3],
                'created_at': str(row[4])
            })
        cur.close()
        conn.close()
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/api/v1/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID - uses parameterized query."""
    try:
        conn = get_db_connection()
        cur = conn.cursor()
        cur.execute("SELECT id, username, department, role, email FROM users WHERE id = %s", (user_id,))
        row = cur.fetchone()
        cur.close()
        conn.close()
        if row:
            return jsonify({'id': row[0], 'username': row[1], 'department': row[2], 'role': row[3], 'email': row[4]})
        return jsonify({'error': 'not found'}), 404
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080, debug=False)
